-- Généré par infrastructure/content/build-verite.mjs : ne pas modifier à la main.
-- 22 entrées, 20 relations.
BEGIN;
DELETE FROM content_relation WHERE from_id IN (SELECT id FROM content_entry WHERE scope = 'verite');
UPDATE content_entry SET status = 'archived', updated_at = now() WHERE scope = 'verite' AND status <> 'archived' AND (type, slug) NOT IN (('regle', 'cadre'), ('regle', 'nature_humain'), ('regle', 'nature_vampire'), ('regle', 'nature_garou'), ('regle', 'nature_khinae'), ('regle', 'nature_mage'), ('regle', 'nature_daemon'), ('regle', 'nature_angelus'), ('regle', 'nature_aseryn'), ('regle', 'nature_exile'), ('regle', 'nature_extral'), ('regle', 'catalogue_humain'), ('regle', 'catalogue_vampire'), ('regle', 'catalogue_garou'), ('regle', 'catalogue_khinae'), ('regle', 'catalogue_mage'), ('regle', 'catalogue_daemon'), ('regle', 'catalogue_angelus'), ('regle', 'catalogue_aseryn'), ('regle', 'catalogue_exile'), ('regle', 'catalogue_extral'), ('regle', 'corruption'));
SELECT e.id, e.version, to_jsonb(e) - 'id', 'Import verite (voies à paliers)'
FROM content_entry e WHERE e.scope = 'verite'
ON CONFLICT (entry_id, version) DO NOTHING;
COMMIT;
